<template>
  <div class="support-center">
    <aside class="conversation-panel">
      <div class="support-panel-head"><div><h2>在线客服</h2><p>{{onlineCount}} 个进行中会话</p></div><button @click="loadConversations">↻</button></div>
      <div class="conversation-search">⌕ <input v-model="keyword" placeholder="搜索用户或消息"></div>
      <div class="conversation-tabs"><button :class="{active:tab==='open'}" @click="tab='open'">接待中 <span>{{openCount}}</span></button><button :class="{active:tab==='all'}" @click="tab='all'">全部会话</button></div>
      <div class="conversation-list">
        <button v-for="c in filtered" :key="c.id" :class="{active:selected?.id===c.id}" @click="selectConversation(c)">
          <i>{{c.user_name.slice(0,1)}}<em v-if="c.status==='open'"></em></i>
          <span><b>{{c.user_name}}</b><small>{{c.last_message||'新会话，等待用户提问'}}</small></span>
          <label><time>{{formatListTime(c.updated_at)}}</time><strong v-if="c.unread_admin">{{c.unread_admin}}</strong></label>
        </button>
        <div v-if="!filtered.length" class="support-empty">暂无客服会话</div>
      </div>
    </aside>

    <main class="chat-panel" v-if="selected">
      <header class="chat-head"><div class="chat-user-avatar">{{selected.user_name.slice(0,1)}}</div><div><h3>{{selected.user_name}}</h3><p><i :class="{online:userOnline}"></i>{{userOnline?'用户当前在线':'用户暂时离线'}} · {{selected.user_id}}</p></div><div class="chat-head-actions"><button @click="$emit('toast','已标记为重点用户')">☆ 重点</button><button v-if="selected.status==='open'" class="finish" @click="finishConversation">结束会话</button><span v-else>已结束</span></div></header>
      <div ref="messageBox" class="admin-messages">
        <div class="conversation-start">会话开始于 {{formatDate(selected.created_at)}}</div>
        <div v-for="m in messages" :key="m.id" class="admin-message" :class="m.sender_role">
          <div v-if="m.sender_role==='user'" class="message-avatar user">{{selected.user_name.slice(0,1)}}</div>
          <div class="message-content"><small>{{m.sender_name}} · {{formatTime(m.created_at)}}</small><div>{{m.content}}</div></div>
          <div v-if="m.sender_role==='admin'" class="message-avatar agent">行</div>
        </div>
        <div v-if="userTyping" class="user-typing">用户正在输入 •••</div>
      </div>
      <footer class="admin-composer">
        <div class="composer-tools"><button @click="insertQuick('您好，请问有什么可以帮您？')">常用语</button><button @click="$emit('toast','图片发送功能已预留')">图片</button><button @click="$emit('toast','订单卡片功能已预留')">订单卡片</button><span :class="{connected:socketConnected}">{{socketConnected?'WebSocket 已连接':'实时通道重连中'}}</span></div>
        <textarea v-model="content" :disabled="selected.status!=='open'" placeholder="输入回复内容，Enter 发送，Shift + Enter 换行" @keydown.enter.exact.prevent="sendMessage"></textarea>
        <div class="composer-foot"><small>快捷回复：<button v-for="q in quickReplies" :key="q" @click="insertQuick(q)">{{q}}</button></small><button class="send-message" :disabled="!content.trim()||!socketConnected||selected.status!=='open'" @click="sendMessage">发送消息</button></div>
      </footer>
    </main>

    <aside class="customer-context" v-if="selected">
      <div class="customer-card"><div class="context-avatar">{{selected.user_name.slice(0,1)}}</div><h3>{{selected.user_name}}</h3><p>{{selected.user_id}}</p><div class="context-tags"><span>备考中</span><span>高意向</span></div></div>
      <section><h4>用户概况</h4><div><span>可用积分</span><b>68</b></div><div><span>上岸进度</span><b>72%</b></div><div><span>收藏路线</span><b>3 条</b></div><div><span>客服会话</span><b>{{selected.status==='open'?'接待中':'已结束'}}</b></div></section>
      <section><h4>兴趣线索</h4><article><i>旅</i><div><b>川西雪山轻徒步</b><small>已加入上岸心愿</small></div></article><article><i class="study">学</i><div><b>备考刷题</b><small>近期高频访问</small></div></article></section>
      <section><h4>最近订单</h4><div class="context-order"><b>泰山经典游 2 天 1 夜</b><small>积分兑换 · 审核中</small></div></section>
    </aside>

    <main v-else class="no-conversation"><i>🎧</i><h2>选择一条会话开始接待</h2><p>用户消息将通过 WebSocket 实时出现在这里</p></main>
  </div>
</template>

<script setup>
import{computed,nextTick,onMounted,onUnmounted,ref}from'vue';import{api,getSupportWebSocketUrl}from'../services/api';
const emit=defineEmits(['toast']);const conversations=ref([]),selected=ref(null),messages=ref([]),keyword=ref(''),tab=ref('open'),content=ref(''),socketConnected=ref(false),userOnline=ref(false),userTyping=ref(false),messageBox=ref(null);const quickReplies=['积分兑换说明','预约须知','人工定制流程'];let socket=null,pollTimer=null,reconnectTimer=null,manualClose=false;
const openCount=computed(()=>conversations.value.filter(c=>c.status==='open').length),onlineCount=openCount;const filtered=computed(()=>conversations.value.filter(c=>(tab.value==='all'||c.status==='open')&&`${c.user_name}${c.user_id}${c.last_message}`.includes(keyword.value)));const formatTime=v=>v?new Date(v).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}):'';const formatDate=v=>v?new Date(v).toLocaleString('zh-CN'):'刚刚';const formatListTime=v=>v?new Date(v).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}):'';
const scrollBottom=()=>nextTick(()=>{if(messageBox.value)messageBox.value.scrollTop=messageBox.value.scrollHeight});const loadConversations=async()=>{try{const list=await api.getSupportConversations();conversations.value=list;if(selected.value){const fresh=list.find(c=>c.id===selected.value.id);if(fresh)Object.assign(selected.value,fresh)}else if(list.length)selectConversation(list[0])}catch{}};
const closeSocket=()=>{manualClose=true;clearTimeout(reconnectTimer);if(socket){socket.close();socket=null}socketConnected.value=false};const connectSocket=()=>{if(!selected.value)return;manualClose=false;socket=new WebSocket(getSupportWebSocketUrl(selected.value.id));socket.onopen=()=>{socketConnected.value=true};socket.onmessage=event=>{const data=JSON.parse(event.data);if(data.type==='message'){if(!messages.value.some(m=>m.id===data.message.id))messages.value.push(data.message);selected.value.last_message=data.message.content;scrollBottom()}else if(data.type==='presence'&&data.role==='user')userOnline.value=data.online;else if(data.type==='typing'&&data.role==='user')userTyping.value=data.typing;else if(data.type==='status')selected.value.status=data.status};socket.onclose=()=>{socketConnected.value=false;if(!manualClose)reconnectTimer=setTimeout(connectSocket,2000)};socket.onerror=()=>{socketConnected.value=false}};
const selectConversation=async c=>{closeSocket();selected.value=c;userOnline.value=false;c.unread_admin=0;try{messages.value=await api.getSupportMessages(c.id)}catch{messages.value=[]}connectSocket();scrollBottom()};const sendMessage=()=>{const text=content.value.trim();if(!text||!socketConnected.value)return;socket.send(JSON.stringify({type:'message',content:text}));content.value=''};const insertQuick=text=>{content.value=text};const finishConversation=async()=>{if(!confirm('确认结束本次客服会话？用户仍可重新发起新会话。'))return;try{selected.value=await api.closeSupportConversation(selected.value.id);emit('toast','客服会话已结束');loadConversations()}catch{emit('toast','结束会话失败')}};
onMounted(()=>{loadConversations();pollTimer=setInterval(loadConversations,5000)});onUnmounted(()=>{clearInterval(pollTimer);closeSocket()})
</script>

