;justify-content:space-between;font-size:9px;padding:6px 0}.customer-context section>div span{color:#84938f}.customer-context article{display:flex;align-items:center;gap:8px;margin:9px 0}.customer-context article>i{font-style:normal;width:29px;height:29px;border-radius:9px;background:#e4f5f1;color:#078c7a;display:grid;place-items:center;font-size:9px}.customer-context article>i.study{background:#fff0e5;color:#d96f30}.customer-context article b,.customer-context article small,.context-order b,.context-order small{display:block;font-size:9px}.customer-context article small,.context-order small{font-size:8px;color:#8c9a97;margin-top:3px}.context-order{background:#f4f7f6;border-radius:8px;padding:10px}.support-empty,.no-conversation{text-align:center;color:#8c9c98}.support-empty{font-size:10px;padding:35px}.no-conversation{display:grid;place-content:center;background:#f7f9f8}.no-conversation i{font-style:normal;font-size:42px}.no-conversation h2{font-size:16px;color:#38534e;margin:12px 0 5px}.no-conversation p{font-size:10px}
